    private fun solve(samples: List<DetectorSample>) = MetalDetectorSolver.solve(630, 90, 416, samples)

    @Test
    fun rightChestRanksFirstEveryRound() {
        rounds.forEachIndexed { i, r -> assertEquals(r.chest, solve(r.samples).ranked.first().offset, "round $i") }
    }

    @Test
    fun neverSolvesToAWrongChest() {
        rounds.forEachIndexed { i, r ->
            for (n in 1..r.samples.size) {
                val solved = solve(r.samples.take(n)).solved
                assertTrue(solved == null || solved == r.chest, "round $i after $n samples solved to $solved")
            }
        }
    }

    @Test
    fun solvesEveryRound() {
        // Pairs needed per round, so a rule change that slows solving shows up here.
        val needed = listOf(7, 1, 1, 1, 1, 1, 1, 3, 1)
        rounds.forEachIndexed { i, r ->
            assertEquals(r.chest, solve(r.samples).solved, "round $i")
            val first = (1..r.samples.size).first { solve(r.samples.take(it)).solved != null }
            assertEquals(needed[i], first, "round $i pairs to solve")
        }
    }

    @Test
    fun unsolvedOffersPossibilities() {
        // Round 0's first pairs fit two chests equally well.
        val sol = solve(rounds[0].samples.take(5))
        assertNull(sol.solved)
        assertEquals(setOf(rounds[0].chest, ChestOffset(-23, -22, 40)), sol.possible.toSet())
    }

    @Test
    fun noSamplesNoAnswer() {
        val sol = solve(emptyList())
        assertNull(sol.solved)
        assertTrue(sol.possible.isEmpty())
    }
